import{_ as r,o as i,c as a,ag as s}from"./chunks/framework.RW_pGwXR.js";const o="/cours/assets/10-insertion-graphique.BVg7OaW-.png",t="/cours/assets/10-configuration-options-graphique.BYPI7Wmj.png",l="/cours/assets/10-options-legende-graphique.B6x-aL3a.png",m=JSON.parse('{"title":"Graphiques","description":"","frontmatter":{"title":"Graphiques"},"headers":[],"relativePath":"modules/02-excel/10-graphiques.md","filePath":"modules/02-excel/10-graphiques.md"}'),n={name:"modules/02-excel/10-graphiques.md"};function u(d,e,p,h,g,c){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="graphiques" tabindex="-1">Graphiques <a class="header-anchor" href="#graphiques" aria-label="Permalink to &quot;Graphiques&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p><a href="https://livecegepfxgqc-my.sharepoint.com/:x:/g/personal/otremblay_cegepgarneau_ca/IQDEFk8w9hsjQq_4KU2HBDmSAWaii9EZpUfgVpk-VAt2-10?e=ccHQ8S" target="_blank" rel="noreferrer">10 – Graphiques</a></p><p>⚠️ Ne travaillez pas dans la version Excel du navigateur Web.</p><p><strong>Veuillez télécharger une copie de chaque exercice.</strong></p><ul><li>Fichier --&gt; Créer une copie --&gt; Télécharger une copie</li></ul><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><ul><li>Créer des graphiques pour visualiser les données</li><li>Choisir le type de graphique approprié selon le contexte</li><li>Personnaliser l&#39;apparence des graphiques</li><li>Modifier et mettre à jour les données d&#39;un graphique</li></ul><h2 id="choix-du-graphique" tabindex="-1">Choix du graphique <a class="header-anchor" href="#choix-du-graphique" aria-label="Permalink to &quot;Choix du graphique&quot;">​</a></h2><p>Chaque type de graphique a un usage précis selon les données à représenter.</p><p><strong>Types de graphiques courants :</strong></p><ul><li><strong>Histogramme (colonnes)</strong> : comparer des valeurs entre différentes catégories</li><li><strong>Graphique en courbes</strong> : montrer l&#39;évolution dans le temps ou les tendances</li><li><strong>Graphique en secteurs (camembert)</strong> : afficher les proportions d&#39;un ensemble (total = 100%)</li><li><strong>Graphique à barres</strong> : similaire à l&#39;histogramme, mais horizontal</li><li><strong>Nuage de points</strong> : montrer la relation entre deux variables numériques</li></ul><h2 id="inserer-un-graphique" tabindex="-1">Insérer un graphique <a class="header-anchor" href="#inserer-un-graphique" aria-label="Permalink to &quot;Insérer un graphique&quot;">​</a></h2><h3 id="ou-est-le-bouton-«-graphiques-»" tabindex="-1">Où est le bouton « Graphiques » ? <a class="header-anchor" href="#ou-est-le-bouton-«-graphiques-»" aria-label="Permalink to &quot;Où est le bouton « Graphiques » ?&quot;">​</a></h3><ul><li>Onglet <strong>Insertion</strong> du ruban</li><li>Groupe <strong>Graphiques</strong></li><li>Choisir le type de graphique souhaité</li></ul><h3 id="procedure" tabindex="-1">Procédure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procédure&quot;">​</a></h3><ol><li><strong>Sélectionner les données</strong> incluant les en-têtes (titres de colonnes)</li><li>Aller dans <strong>Insertion</strong> &gt; <strong>Graphiques</strong></li><li>Choisir le type de graphique approprié <ul><li>Pour comparer : <strong>Histogramme</strong></li><li>Pour l&#39;évolution : <strong>Courbes</strong></li><li>Pour les proportions : <strong>Secteurs</strong></li></ul></li><li>Le graphique s&#39;insère automatiquement dans la feuille</li></ol><img src="'+o+'" alt="Insertion d&#39;un graphique" class="img-bordered"><div class="tip custom-block"><p class="custom-block-title">Conseil</p><p>Assurez-vous que vos données sont bien organisées en colonnes avec des en-têtes clairs avant de créer le graphique.</p></div><h2 id="edition-et-personnalisation" tabindex="-1">Édition et personnalisation <a class="header-anchor" href="#edition-et-personnalisation" aria-label="Permalink to &quot;Édition et personnalisation&quot;">​</a></h2><h3 id="modifier-le-titre-du-graphique" tabindex="-1">Modifier le titre du graphique <a class="header-anchor" href="#modifier-le-titre-du-graphique" aria-label="Permalink to &quot;Modifier le titre du graphique&quot;">​</a></h3><ol><li>Cliquer sur le <strong>titre du graphique</strong></li><li>Taper le nouveau titre directement</li></ol><h3 id="ajouter-ou-modifier-les-titres-des-axes" tabindex="-1">Ajouter ou modifier les titres des axes <a class="header-anchor" href="#ajouter-ou-modifier-les-titres-des-axes" aria-label="Permalink to &quot;Ajouter ou modifier les titres des axes&quot;">​</a></h3><ol><li>Cliquer sur le graphique</li><li>Aller dans <strong>Création de graphique</strong> (onglet contextuel)</li><li>Cliquer sur <strong>Ajouter un élément de graphique</strong> &gt; <strong>Titres des axes</strong></li><li>Choisir <strong>Axe horizontal principal</strong> ou <strong>Axe vertical principal</strong></li><li>Modifier le texte du titre</li></ol><h3 id="modifier-les-couleurs-et-le-style" tabindex="-1">Modifier les couleurs et le style <a class="header-anchor" href="#modifier-les-couleurs-et-le-style" aria-label="Permalink to &quot;Modifier les couleurs et le style&quot;">​</a></h3><ol><li>Cliquer sur le graphique</li><li>Utiliser les boutons rapides à droite du graphique : <ul><li><strong>Styles du graphique</strong> (pinceau) : changer les couleurs et le style</li><li><strong>Éléments de graphique</strong> (+) : ajouter/retirer des éléments (légende, quadrillage, etc.)</li><li><strong>Filtres de graphique</strong> (entonnoir) : afficher/masquer des séries de données</li></ul></li></ol><img src="'+t+'" alt="Options de configuration du graphique" class="img-bordered"><h3 id="modifier-la-legende" tabindex="-1">Modifier la légende <a class="header-anchor" href="#modifier-la-legende" aria-label="Permalink to &quot;Modifier la légende&quot;">​</a></h3><ol><li>Cliquer sur la légende</li><li>La déplacer en la faisant glisser</li><li>Utiliser les options à droite pour la positionner (en haut, à droite, etc.)</li></ol><img src="'+l+'" alt="Options de légende du graphique" class="img-bordered">',30)])])}const f=r(n,[["render",u]]);export{m as __pageData,f as default};
